import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { parseEnv } from 'node:util';

/**
 * Microservice config. Precedence: real environment > services/<name>/.env > backend/.env
 *   services/<name>/.env — this service only: PORT, DATABASE_URL, its own secrets
 *   backend/.env         — shared NON-secret settings (brokers, issuers, OPA, OTel …)
 * Both are generated by `ac configure` (platform repo). In AWS everything comes from the task definition.
 */
export function loadServiceEnv(serviceDir = process.cwd()) {
  const read = (file: string) => (existsSync(file) ? parseEnv(readFileSync(file, 'utf8')) : {});
  let root = serviceDir;
  while (!existsSync(join(root, 'pnpm-workspace.yaml')) && dirname(root) !== root) root = dirname(root);
  const shared = root === serviceDir ? {} : read(join(root, '.env'));
  const merged = { ...shared, ...read(join(serviceDir, '.env')) };
  for (const [k, v] of Object.entries(merged)) if (process.env[k] === undefined && v !== undefined) process.env[k] = v;
}

/** @deprecated use loadServiceEnv */
export const loadRootEnv = loadServiceEnv;
